 mat(color,glow=0){const key=color+':'+glow;if(!this.materials.has(key)){const mat=new T.MeshStandardMaterial({color,roughness:.72,metalness:.1,emissive:color,emissiveIntensity:glow,flatShading:true});this.materials.set(key,mat);}return this.materials.get(key);}
